<script setup>
import { assetUrl } from '../lib/assets.js'
import { computed,ref,watch,onBeforeUnmount } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ArrowRight,ArrowLeft,CheckCircle2,Headphones,Image,FilePenLine,Video,ShieldCheck,Info,Clock,Wallet,ClipboardCheck } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import PageTitle from '../components/PageTitle.vue'
import FileUpload from '../components/FileUpload.vue'
import { state,templates,money,saveDraft,uid,stamp,imageOf } from '../lib/store'
import { requireRole,confirm,notify } from '../lib/actions'
const route=useRoute(),router=useRouter(),step=computed(()=>route.meta.step),draft=state.draft,form=ref(null),saving=ref(false),busy=ref(false)
const selected=computed(()=>templates.find(t=>t.name===draft.category)||templates[0]),submitted=ref(null)
const rules={title:[{required:true,min:5,max:50,message:'任务标题须为 5–50 字',trigger:'blur'}],description:[{required:true,min:10,max:2000,message:'需求描述须为 10–2000 字',trigger:'blur'}],bounty:[{required:true,type:'number',min:30,max:50000,message:'赏金范围为 ¥30–50,000',trigger:'change'}],authorization:[{required:true,min:5,message:'请说明原图授权情况（至少 5 字）',trigger:'blur'}]}
let timer;watch(draft,()=>{saving.value=true;clearTimeout(timer);timer=setTimeout(()=>{saveDraft();saving.value=false},30000)},{deep:true});onBeforeUnmount(()=>{clearTimeout(timer);if(saving.value)saveDraft()})
function choose(t){if(t.disabled)return;draft.category=t.name;draft.count=t.count;draft.tags=['场景图','精修'];draft.format=t.name==='短视频'?'MP4':t.name==='营销文案'?'DOCX / TXT':'JPG / PNG';draft.size=t.name==='模特换装'?'750 × 1000':'800 × 800'}
function sample(){draft.files=[1,2,3].map(i=>({uid:`reference-${i}`,name:`示例参考-${i}.jpg`,image:assetUrl(`pages/delivery-${i}.webp`),size:180000,type:'image'}));if(!draft.title)draft.title=`${draft.category==='商品主图'?'护肤新品主图设计':draft.category+'制作'} · ${draft.count}${selected.value.unit}`;if(!draft.description)draft.description='为新品制作电商内容，突出产品质感与核心卖点。保留商品外观与包装信息，采用温暖自然的光影，整体风格简洁统一。';notify('已填入设计稿中的示例需求，可继续修改')}
const deliverySummary=computed(()=>{
 const size=draft.size==='自定义'?draft.customSize:draft.size
 const source=draft.sourceFile?'，含可编辑源文件':''
 if(draft.category==='短视频')return `${draft.count} 条 ${draft.duration} 视频，1080 × 1920 px，MP4 格式${draft.script?'，含脚本':''}${draft.subtitles?'，含配音字幕':''}`
 if(draft.category==='营销文案')return `${draft.count} 篇${draft.platform}文案，每篇 ${draft.words==='自定义'?draft.customWords:draft.words} 字${draft.multiTitles?'，各附 3 版标题':''}`
 if(draft.category==='详情页')return `${draft.count} 套详情页，每套 ${draft.pages} 屏，750 px 宽，${draft.format}${draft.copy?'，含卖点文案':''}${source}`
 return `${draft.count} 张高清${draft.category}，${size} px，${draft.format}${source}`
})
function validateData(){return draft.title.trim().length>=5&&draft.description.trim().length>=10&&draft.files.length>0&&draft.bounty>=30&&draft.bounty<=50000}
async function next(){try{await form.value.validate()}catch{ElMessage.warning('请完成表单中的必填信息');return}if(!draft.files.length){ElMessage.warning('请至少添加 1 个参考素材，也可使用示例需求');return}if(draft.category==='商品主图'&&!draft.tags.length){ElMessage.warning('请至少选择一种图类型');return}if(['商品主图','模特换装'].includes(draft.category)&&draft.size==='自定义'&&!/^\d{2,5}\s*[×xX*]\s*\d{2,5}$/.test(draft.customSize)){ElMessage.warning('请填写自定义尺寸，例如 1200 × 1600');return}if(draft.category==='短视频'&&!draft.videoTypes.length){ElMessage.warning('请选择至少一种视频类型');return}if(draft.category==='模特换装'&&!draft.style.length){ElMessage.warning('请选择模特风格');return}const unitPrice=draft.bounty/draft.count;if((unitPrice<selected.value.low||unitPrice>selected.value.high)&&!(await confirm(`当前单价 ¥${unitPrice.toFixed(2)} 超出类目指导价 ${selected.value.price}，仍然继续吗？`,'确认赏金')))return;saveDraft();router.push('/publish/payment')}
function persist(){saveDraft();saving.value=false;notify('需求草稿已保存在当前浏览器')}
async function pay(){if(busy.value)return;if(!requireRole(router,'merchant',true))return;if(!validateData()){ElMessage.warning('请先填写需求并上传素材');router.push('/publish/requirements');return}if(!(await confirm(`本次仅模拟托管 ¥${draft.bounty.toFixed(2)}，不会扣款。确认后任务进入“审核中”。`,'演示支付确认')))return;busy.value=true;const t={id:uid('T'),title:draft.title,category:draft.category,mode:draft.mode,price:draft.bounty,cents:Math.round(draft.bounty*100),art:selected.value.art||'skincare',image:imageOf(selected.value.art||'skincare'),description:draft.description,deliverables:deliverySummary.value+(draft.requirements?'；'+draft.requirements:''),days:draft.days,revisions:draft.revisions,remaining:72,filled:0,capacity:draft.mode==='一口价'?1:draft.slots,bids:0,status:'审核中',updated:stamp(),publishedOrder:Date.now()};state.tasks.unshift(t);state.merchantFlows.unshift({id:uid('MF'),at:stamp(),type:'托管冻结',title:t.title,cents:t.cents,status:'演示托管',ref:uid('DEMO')});submitted.value=t;notify('模拟托管完成，任务已进入审核中');busy.value=false}
</script>
<template><div class="publish-page">
 <PageTitle :title="step===0?'发布任务':step===1?`填写${draft.category}需求`:'确认需求并托管赏金'" :description="step===0?'用清晰的需求，开启一次高效合作。':undefined"><el-button v-if="step===1" @click="sample">填入示例需求</el-button></PageTitle>
 <el-steps :active="step" finish-status="success" align-center><el-step title="选择模板"/><el-step title="填写需求"/><el-step title="托管赏金"/></el-steps>
 <template v-if="step===0"><section class="panel"><div class="template-grid"><button v-for="t in templates" :key="t.name" :class="['template-card',{selected:draft.category===t.name}]" :disabled="t.disabled" @click="choose(t)"><div class="template-art"><img v-if="t.art" :src="imageOf(t.art)" :alt="t.name+'参考图'"/><component v-else :is="t.name==='营销文案'?FilePenLine:Video" :size="64"/><span v-if="draft.category===t.name" class="template-check"><CheckCircle2 :size="24"/></span><span v-if="t.disabled" class="gray-label">灰度开放</span></div><div class="template-card-body"><div><h2>{{t.name}}</h2><span :class="{'price-text':!t.disabled}">{{t.price}}</span></div><p>{{t.description}}</p><span class="template-select">{{t.disabled?'暂未开放':'选择模板'}}<ArrowRight :size="16"/></span></div></button></div><div class="page-actions"><RouterLink class="help-link" to="/messages?chat=support&role=merchant"><Headphones :size="18"/> 不确定如何描述需求？联系客服。</RouterLink><el-button @click="router.push('/merchant/tasks')">返回任务管理</el-button><el-button type="primary" @click="router.push('/publish/requirements')">下一步，填写需求 <ArrowRight/></el-button></div></section></template>
 <template v-else-if="step===1"><div class="columns wide-left"><section class="panel"><el-form ref="form" :model="draft" :rules="rules" label-position="left" label-width="95px"><h2 class="form-section-title">基本信息</h2><el-form-item label="任务标题" prop="title"><el-input v-model="draft.title" placeholder="用一句话说明要完成什么内容" maxlength="50" show-word-limit/></el-form-item><el-form-item label="商品链接"><el-input v-model="draft.link" placeholder="选填：粘贴商品链接，当前演示请手动填写商品信息"/></el-form-item><el-form-item label="需求描述" prop="description"><el-input v-model="draft.description" type="textarea" :rows="4" maxlength="2000" show-word-limit placeholder="描述产品、用途、风格、核心卖点与希望避免的内容……"/></el-form-item><el-form-item label="参考素材" required><FileUpload v-model="draft.files"/></el-form-item><div class="divider"/><h2 class="form-section-title">交付要求</h2><div :class="['form-grid',draft.category==='商品主图'?'four':'three']"><el-form-item :label="`${selected.unit==='张'?'张数':selected.unit==='条'?'条数':selected.unit==='篇'?'篇数':'套数'}`" required><el-input-number v-model="draft.count" :min="1" :max="draft.category==='详情页'?5:draft.category==='短视频'?10:draft.category==='营销文案'?20:50" :precision="0"/></el-form-item><el-form-item v-if="draft.category==='商品主图'||draft.category==='模特换装'" label="尺寸规范" required><el-select v-model="draft.size"><el-option v-for="x in ['800 × 800','800 × 1200','750 × 1000','自定义']" :key="x" :value="x"/></el-select></el-form-item><el-form-item label="文件格式"><el-select v-model="draft.format"><el-option v-for="x in ['JPG / PNG','PNG','PSD + JPG','MP4','DOCX / TXT']" :key="x" :value="x"/></el-select></el-form-item><el-form-item v-if="draft.category==='商品主图'" label="图类型" required><el-select v-model="draft.tags" multiple><el-option v-for="x in ['白底图','场景图','精修','换背景']" :key="x" :value="x"/></el-select></el-form-item></div>
 
 <el-form-item v-if="['商品主图','模特换装'].includes(draft.category)&&draft.size==='自定义'" label="自定义尺寸" required><el-input v-model="draft.customSize" placeholder="例如：1200 × 1600（px）" maxlength="20"/></el-form-item>
 <template v-if="draft.category==='模特换装'"><el-form-item label="模特风格" required><el-checkbox-group v-model="draft.style"><el-checkbox v-for="x in ['亚洲','欧美','大码','少年感','轻熟']" :key="x" :value="x">{{x}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="场景"><el-select v-model="draft.scene" multiple><el-option v-for="x in ['街拍','居家','咖啡馆','办公室','纯色']" :key="x" :value="x"/></el-select></el-form-item><el-form-item label="原图授权说明" prop="authorization"><el-input v-model="draft.authorization" placeholder="请说明真人原图的使用授权情况"/></el-form-item></template>
 <template v-if="draft.category==='短视频'"><div class="form-grid"><el-form-item label="单条时长" required><el-select v-model="draft.duration"><el-option v-for="x in ['15s','30s','60s']" :key="x" :value="x"/></el-select></el-form-item><el-form-item label="视频类型" required><el-select v-model="draft.videoTypes" multiple><el-option v-for="x in ['商品切片','真人口播','数字人口播','图转视频']" :key="x" :value="x"/></el-select></el-form-item></div><div class="inline-actions"><el-checkbox v-model="draft.script">包含脚本</el-checkbox><el-checkbox v-model="draft.subtitles">包含配音字幕</el-checkbox></div></template>
 <template v-if="draft.category==='详情页'"><el-form-item label="页面数" required><el-input-number v-model="draft.pages" :min="3" :max="20" :precision="0"/></el-form-item><el-checkbox v-model="draft.copy">包含卖点文案</el-checkbox></template>
 <template v-if="draft.category==='营销文案'"><div class="form-grid"><el-form-item label="发布平台" required><el-select v-model="draft.platform"><el-option v-for="x in ['小红书','抖音','淘宝','公众号']" :key="x" :value="x"/></el-select></el-form-item><el-form-item label="每篇字数" required><el-select v-model="draft.words"><el-option v-for="x in ['300','500','800','自定义']" :key="x" :value="x"/></el-select></el-form-item></div><el-form-item v-if="draft.words==='自定义'" label="自定义字数" required><el-input-number v-model="draft.customWords" :min="50" :max="10000" :precision="0"/></el-form-item><el-checkbox v-model="draft.multiTitles">每篇提供 3 版标题</el-checkbox></template>
 <el-collapse class="requirements-extra"><el-collapse-item title="其他交付要求（选填）" name="requirements"><el-input v-model="draft.requirements" type="textarea" :rows="2" maxlength="500" placeholder="尺寸规范、品牌色卡、源文件、自定义要求等"/><el-button link type="primary" @click="draft.requirements='保留包装与品牌信息，不使用未经授权的真人形象。请交付高清作品与可编辑源文件。'">插入交付要求模板</el-button><el-checkbox v-model="draft.sourceFile">需要可编辑源文件</el-checkbox></el-collapse-item></el-collapse><div class="divider"/><h2 class="form-section-title">合作设置</h2><div class="form-grid four"><el-form-item label="总赏金（元）" prop="bounty"><el-input-number v-model="draft.bounty" :min="30" :max="50000" :precision="2" :controls="false"/></el-form-item><el-form-item label="完成期限" required><el-select v-model="draft.days"><el-option v-for="n in [1,2,3,5,7]" :key="n" :value="n" :label="`${n} 天`"/></el-select></el-form-item><el-form-item label="免费修改" required><el-select v-model="draft.revisions"><el-option v-for="n in [0,1,2,3,4,5]" :key="n" :value="n" :label="`${n} 轮`"/></el-select></el-form-item><el-form-item label="接单模式" required><el-select v-model="draft.mode"><el-option value="一口价"/><el-option value="比稿"/></el-select></el-form-item></div><p class="field-help">类目指导价：{{selected.price}}。商家侧不收取服务费。</p><el-collapse><el-collapse-item title="高级设置" name="advanced"><div class="advanced-options"><label>仅认证创作者可接 <el-switch v-model="draft.certifiedOnly"/></label><label>允许申请延期 <el-switch v-model="draft.allowExtension"/></label><label v-if="draft.mode==='比稿'">中标名额 <el-input-number v-model="draft.slots" :min="1" :max="3" :precision="0"/></label></div></el-collapse-item></el-collapse></el-form></section><aside class="panel publish-summary"><div class="summary-blue"><Image :size="32"/><div><h2>{{draft.category}}</h2><p>{{draft.count}}{{selected.unit}} / {{draft.days}} 天 / 免费修改 {{draft.revisions}} 轮</p></div></div><div class="data-lines"><div><label>任务赏金</label><strong class="price-text big-number">¥{{money(Math.round(draft.bounty*100))}}</strong></div><div><label>商家服务费</label><strong>¥0.00</strong></div><div><label>应付合计</label><strong class="price-text big-number">¥{{money(Math.round(draft.bounty*100))}}</strong></div></div><div class="info-note" style="margin-top:22px"><ShieldCheck/><div>商家侧不收取服务费<br/>赏金托管，验收后结算</div></div></aside></div><div class="page-actions"><span class="auto-save"><CheckCircle2 :size="16"/>{{saving?'草稿保存中…':state.lastSaved?'草稿已保存 '+state.lastSaved:'需求仅保存在当前浏览器'}}</span><el-button @click="router.push('/publish/template')">上一步</el-button><el-button @click="persist">保存草稿</el-button><el-button type="primary" @click="next">下一步，托管赏金<ArrowRight/></el-button></div></template>
 <template v-else><template v-if="submitted"><section class="panel payment-success"><CheckCircle2 :size="64"/><h2>模拟托管完成，任务正在审核</h2><p>{{submitted.title}}</p><p class="muted">未发生真实扣款。你可以在任务管理中继续体验审核与上架状态。</p><el-button type="primary" @click="router.push('/merchant/tasks')">查看我的任务<ArrowRight/></el-button></section></template><template v-else><div class="columns"><div class="stack"><section class="panel"><h2>任务需求确认</h2><div class="payment-task"><img :src="imageOf(selected.art||'skincare')" alt="任务参考图"/><div><h2>{{draft.title||'尚未填写任务标题'}}</h2><div class="tag-row"><span class="plain-tag">{{draft.category}}</span><span class="plain-tag">{{draft.mode}}</span></div><p>{{draft.days}} 天交付 · 免费修改 {{draft.revisions}} 轮</p></div></div><div class="divider"/><h3>参考素材（{{draft.files.length}}）</h3><div class="payment-files"><div v-for="f in draft.files" :key="f.uid"><img v-if="f.image" :src="f.image" :alt="f.name"/><span v-else>{{f.name}}</span></div></div><el-button v-if="!validateData()" link type="primary" @click="router.push('/publish/requirements')">需求未完整，请先返回填写</el-button></section><section class="panel"><h2>支付方式</h2><div class="payment-placeholder"><div class="payment-symbol"><Wallet :size="58"/><span>支付接入预留区</span></div><div><h3>当前为托管流程演示</h3><p class="muted">支付服务尚未接入，无需扫码或转账。</p><p class="field-help">点击下方按钮，可体验支付后的任务状态。</p></div></div><div class="info-note"><Info/>平台外交易无保障，请勿向私人账户转账。</div></section></div><aside class="stack"><section class="panel"><h2>账单明细</h2><div class="data-lines"><div><label>任务赏金</label><strong>¥{{money(Math.round(draft.bounty*100))}}</strong></div><div><label>商家服务费</label><strong>¥0.00</strong></div><div><label>应付合计</label><strong class="big-number price-text">¥{{money(Math.round(draft.bounty*100))}}</strong></div></div></section><section class="panel"><h3>资金托管保障</h3><p class="muted">正式服务中，赏金由支付机构托管，验收通过后结算，保障双方权益。</p><div class="payment-flow"><div><Wallet/>支付托管</div><ArrowRight/><div><ClipboardCheck/>审核上架</div><ArrowRight/><div><ShieldCheck/>验收结算</div></div><div class="info-note">支付成功后进入审核，审核结果将通过站内消息通知。</div></section></aside></div><div class="page-actions"><el-button @click="router.push('/publish/requirements')"><ArrowLeft/>返回修改</el-button><el-button link type="primary" @click="router.push('/messages?chat=support&role=merchant')">支付遇到问题？联系客服</el-button><el-button type="primary" :loading="busy" @click="pay">模拟支付，体验后续流程<ArrowRight/></el-button></div></template></template>
</div></template>
